/* TU-private list types (the shapes of sly2/basic.h's DL and sly2/dli.h's DLI; private so the inline DLI helpers
   below stay as the per-function file wrote them). */
struct DL { void *pvFirst; void *pvLast; int ibDle; };
struct DLE { void *pvNext; void *pvPrev; };
struct DLI { DL *pdl; void **ppv; int ibDle; DLI *pdliNext; int nUnused; };

/* A constraint (0x28): kind (1: always active), bounds, current value and residual, its row of the matrix. */
struct DZ
{
    int nKind;      /* +0x00 */
    float gMin;     /* +0x04 */
    float gMax;     /* +0x08 */
    float gC;       /* +0x0C solution */
    float g10;      /* +0x10 residual */
    float g14;      /* +0x14 residual change per unit step */
    float *ag;      /* +0x18 row */
    int n1C;
    DLE dle;        /* +0x20 */
};
typedef char assert_DZ_size[sizeof(DZ) == 0x28 ? 1 : -1];

/* The solver: constraints, the four lists, the active count and the Crout work arrays. */
struct DZG
{
    int cdzMax;     /* +0x00 */
    int cdz;        /* +0x04 */
    DZ *adz;        /* +0x08 */
    DL dlA;         /* +0x0C active */
    DL dlB;         /* +0x18 at the lower bound */
    DL dlC;         /* +0x24 at the upper bound */
    DL dlD;         /* +0x30 free */
    int cdzA;       /* +0x3C size of dlA */
    float *agMat;   /* +0x40 */
    float *agLu;    /* +0x44 */
    float *agB;     /* +0x48 */
    float *agX;     /* +0x4C */
};
typedef char assert_DZG_size[sizeof(DZG) == 0x50 ? 1 : -1];

